// max-size = 100 items, max-wait = 10ms (whichever fires first)
const MAX_SIZE = 100, MAX_WAIT = 10;
let buffer = [], timer = null;
function flush(reason) {
  if (buffer.length === 0) return;
  console.log(`flush ${buffer.length} (${reason})`);
  buffer = [];
  if (timer) { clearTimeout(timer); timer = null; }
}
function add(item) {
  buffer.push(item);
  if (buffer.length >= MAX_SIZE) { flush('size'); return; }
  if (!timer) timer = setTimeout(() => { timer = null; flush('time'); }, MAX_WAIT);
}
// slow burst: one item, then idle past the deadline
add('a');
// fast burst: 250 items at once -> should size-flush twice, leave 50 for the timer
for (let i = 0; i < 250; i++) add(i);

